import os
import boto3
from botocore.exceptions import ClientError

def validate_document_fields(payload, config=None):
    config = config or {}
    client = boto3.client('textract', region_name=config.get('region', 'us-east-1'))
    try:
        if 'file_bytes' in payload:
            response = client.analyze_document(
                Document={'Bytes': payload['file_bytes']},
                FeatureTypes=['FORMS']
            )
        elif 's3_bucket' in payload and 's3_key' in payload:
            response = client.analyze_document(
                Document={'S3Object': {'Bucket': payload['s3_bucket'], 'Name': payload['s3_key']}},
                FeatureTypes=['FORMS']
            )
        else:
            return {'valid': False, 'error': 'Invalid payload format'}
        required_fields = config.get('required_fields', [])
        extracted = {}
        for block in response['Blocks']:
            if block['BlockType'] == 'KEY_VALUE_SET' and 'KEY' in block['EntityTypes']:
                for rel in block.get('Relationships', []):
                    if rel['Type'] == 'VALUE':
                        key_text = ''
                        value_text = ''
                        key_confidence = 0.0
                        value_confidence = 0.0
                        for id in block['Ids']:
                            key_block = next((b for b in response['Blocks'] if b['Id'] == id), None)
                            if key_block and key_block['BlockType'] == 'WORD':
                                key_text += key_block['Text'] + ' '
                                key_confidence = max(key_confidence, key_block.get('Confidence', 0.0))
                        for id in rel['Ids']:
                            value_block = next((b for b in response['Blocks'] if b['Id'] == id), None)
                            if value_block and value_block['BlockType'] == 'WORD':
                                value_text += value_block['Text'] + ' '
                                value_confidence = max(value_confidence, value_block.get('Confidence', 0.0))
                        field_name = key_text.strip().lower()
                        extracted[field_name] = {
                            'value': value_text.strip(),
                            'confidence': value_confidence
                        }
        validation = {}
        for field in required_fields:
            field_lower = field.lower()
            if field_lower in extracted:
                validation[field] = {
                    'present': True,
                    'confidence': extracted[field_lower]['confidence'],
                    'value': extracted[field_lower]['value']
                }
            else:
                validation[field] = {'present': False, 'confidence': 0.0, 'value': None}
        all_present = all(v['present'] for v in validation.values())
        min_confidence = config.get('min_confidence', 80.0)
        all_confident = all(v['confidence'] >= min_confidence for v in validation.values() if v['present'])
        result = {
            'valid': all_present and all_confident,
            'validation': validation,
            'extracted': extracted
        }
    except ClientError as e:
        result = {'valid': False, 'error': str(e)}
    return result
